//! Vectors for `layout_read`, generated by `scripts/cpp_vectors/frame_layout_vectors.cpp` from
//! `fixtures/config/layout.txt` (`blocks/frame/req_frame.h:74-104`).

use std::collections::HashMap;

use fp_core::frame::req_frame::{layout_read, LayoutLines};

const VECTORS: &str = include_str!("../../fixtures/frame_layout_vectors.txt");

fn unhex(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    assert!(b.len() % 2 == 0, "odd hex length");
    let mut v = Vec::with_capacity(b.len() / 2);
    for p in b.chunks_exact(2) {
        v.push((hexval(p[0]) << 4) | hexval(p[1]));
    }
    v
}

fn hexval(c: u8) -> u8 {
    match c {
        b'0'..=b'9' => c - b'0',
        b'a'..=b'f' => c - b'a' + 10,
        _ => panic!("bad hex digit {}", c as char),
    }
}

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

#[test]
fn layout_read_matches_the_cpp_reference() {
    let mut lines = VECTORS.lines();
    let mut seen = 0usize;
    while let Some(line) = lines.next() {
        if !line.starts_with("LAYOUT ") {
            continue;
        }
        let kv = fields(line);
        let name = kv["name"];
        let text = String::from_utf8(unhex(kv["input"])).unwrap();
        let mut parsed = LayoutLines::default();
        let got = layout_read(&text, &mut parsed);
        let why = if kv["why"] == "-" { String::new() } else { String::from_utf8(unhex(kv["why"])).unwrap() };
        match (kv["ok"], got) {
            ("1", None) => assert!(why.is_empty(), "{}: accepted with a reason", name),
            ("0", Some(e)) => assert_eq!(e, why, "{}: rejection text", name),
            _ => panic!("{}: ok flag {} but parser returned {:?}", name, kv["ok"], got),
        }
        let ngroups: usize = kv["groups"].parse().unwrap();
        let nblocks: usize = kv["blocks"].parse().unwrap();
        assert_eq!(parsed.groups.len(), ngroups, "{}: group count", name);
        assert_eq!(parsed.blocks.len(), nblocks, "{}: block count", name);
        for (i, g) in parsed.groups.iter().enumerate() {
            let line = lines.next().unwrap();
            let gv = fields(line);
            assert_eq!(g.link.to_string(), gv["link"], "{}: group {} link", name, i);
            assert_eq!(g.moment.to_string(), gv["moment"], "{}: group {} moment", name, i);
            assert_eq!(g.group.to_string(), gv["group"], "{}: group {} group", name, i);
            assert_eq!((g.cls as char).to_string(), gv["cls"], "{}: group {} class", name, i);
            assert_eq!(g.rows.to_string(), gv["rows"], "{}: group {} rows", name, i);
            assert_eq!(g.life.to_string(), gv["life"], "{}: group {} life", name, i);
        }
        for (i, b) in parsed.blocks.iter().enumerate() {
            let line = lines.next().unwrap();
            let bv = fields(line);
            assert_eq!(b.link.to_string(), bv["link"], "{}: block {} link", name, i);
            assert_eq!(b.moment.to_string(), bv["moment"], "{}: block {} moment", name, i);
            assert_eq!(b.group.to_string(), bv["group"], "{}: block {} group", name, i);
            assert_eq!(b.array.to_string(), bv["array"], "{}: block {} array", name, i);
            assert_eq!(b.at.first_i.to_string(), bv["first_i"], "{}: block {} first_i", name, i);
            assert_eq!(b.at.bits_i.to_string(), bv["bits_i"], "{}: block {} bits_i", name, i);
            assert_eq!(b.at.first_c.to_string(), bv["first_c"], "{}: block {} first_c", name, i);
            assert_eq!(b.at.bits_c.to_string(), bv["bits_c"], "{}: block {} bits_c", name, i);
            assert_eq!((b.at.i_is_low as u8).to_string(), bv["i_is_low"], "{}: block {} low", name, i);
            assert_eq!(b.at.first_row.to_string(), bv["first_row"], "{}: block {} row", name, i);
            assert_eq!(b.at.first_place.to_string(), bv["first_place"], "{}: block {} place", name, i);
            assert_eq!(b.at.row_bits.to_string(), bv["row_bits"], "{}: block {} row_bits", name, i);
            assert_eq!(b.at.place_bits.to_string(), bv["place_bits"], "{}: block {} place_bits", name, i);
        }
        seen += 1;
    }
    assert!(seen >= 20, "only {} layout cases", seen);
}
